import {catalogNodes,rootById,nodesByPath,nodeTrail} from './catalog-tree.mjs';
import {photoMarkup} from './catalog-media.mjs';
import {normalizeSearch,searchSolutions} from './project-utils.mjs';
export const partitionModels=catalogNodes.filter(n=>n.category==='partitions'&&n.isLeaf);
const fields=[['system','Система','systemId','system'],['application','Где установить','applicationId','application'],['opening','Открывание','openingId','opening'],['glazing','Остекление','glazingId','glazing'],['color','Цвет стекла','materialColorId','materialColor'],['treatment','Обработка стекла','glassTreatmentId','glassTreatment'],['decor','Декор','decorId','decor'],['blinds','Жалюзи','blindsId','blinds']];
export const partitionFacetDefs=fields.map(([id,title,key,label])=>({id,title,key,label,options:[...new Map(partitionModels.filter(n=>n.preset?.[key]).map(n=>[String(n.preset[key]),{id:String(n.preset[key]),title:String(n.preset[label]||n.preset[key])}])).values()]}));
const asParams=p=>p&&typeof p.get==='function'?p:new URLSearchParams(p||'');
export function filterPartitionModels(params=new URLSearchParams()){
 const p=asParams(params);let found=partitionModels.filter(n=>partitionFacetDefs.every(f=>!p.get(f.id)||String(n.preset?.[f.key]||'')===p.get(f.id))&&(!p.get('thickness')||Number(n.preset?.thicknessMm)>0&&Number(n.preset.thicknessMm)===Number(p.get('thickness'))));
 if(normalizeSearch(p.get('q')||'')){const records=found.map(node=>({id:node.path,title:node.title,description:node.intro,category:'partitions',features:node.preset,tags:nodeTrail(node).map(n=>n.title),node}));found=searchSolutions(records,[],p.get('q')).map(r=>r.node);}
 return found;
}
export function createPartitionsUI({esc,btn,crumb,finalCard}){
 const root=()=>rootById.get('partitions');
 const count=n=>`${n} ${n%100>=11&&n%100<=14?'вариантов':n%10===1?'вариант':n%10>=2&&n%10<=4?'варианта':'вариантов'}`;
 const entryLabels={'all-glass':'Цельностеклянные',framed:'Каркасные',loft:'Лофт',smart:'SMART'};
 const entryDescriptions={'all-glass':'Стекло с локальными креплениями',framed:'Один или два ряда стекла в профиле',loft:'Выразительная рама со стеклом',smart:'Стекло с управляемой видимостью'};
 function systemCard(node){return `<a class="partition-entry-card${node.id==='smart'?' partition-entry-smart':''}" href="${node.url}" data-choice-path="${node.path}"><div class="partition-entry-heading"><h2>${esc(entryLabels[node.id]||node.title)}</h2><span aria-hidden="true">↗</span></div><div class="partition-entry-photo">${photoMarkup(node,{eager:true})}</div><p>${esc(entryDescriptions[node.id]||node.intro)}</p></a>`;}
 function subcards(node){return `<nav class="partition-system-subcards" aria-label="Подразделы: ${esc(node.title)}">${node.children.map(child=>`<a href="${child.url}" data-choice-path="${child.path}"><div class="partition-subcard-photo">${photoMarkup(child,{small:true})}</div><div class="partition-subcard-copy"><strong>${esc(child.title)}</strong><span>${count(child.leafCount)} ↗</span></div></a>`).join('')}</nav>`;}
 function directory(){return `<section class="partition-directory" aria-labelledby="partition-directory-title"><h2 id="partition-directory-title">Разновидности по направлениям</h2><p>Раскройте раздел, чтобы сразу перейти к месту установки, конструкции или стеклу.</p><div class="partition-directory-sections">${root().children.map(node=>`<details class="partition-directory-section${node.id==='smart'?' partition-directory-smart':''}"><summary><h3>${esc(entryLabels[node.id]||node.title)}</h3><span>${count(node.leafCount)}</span><b aria-hidden="true">+</b></summary>${subcards(node)}</details>`).join('')}</div></section>`;}
 function systemNavigation(node){if(node?.category!=='partitions')return '';const family=node.depth===2?node.id:node.preset?.systemId||node.systemId;return `<nav class="partition-system-nav" aria-label="Каталоги перегородок"><a href="/catalog/partitions" ${node.depth===1?'aria-current="page"':''}>Все перегородки</a>${root().children.map(n=>`<a href="${n.url}" ${family===n.id?'aria-current="page"':''}>${n.id==='smart'?'SMART':esc(n.title)}</a>`).join('')}<a href="/catalog/partitions?pick=1" class="partition-filter-link">Подбор по параметрам ↗</a></nav>`;}
 function select(def,params){const current=params.get(def.id)||'';return `<label for="partition-filter-${def.id}">${esc(def.title)}<select id="partition-filter-${def.id}" name="${def.id}"><option value="">${def.id==='system'?'Все системы':def.id==='application'?'Любое пространство':'Все варианты'}</option>${def.options.map(o=>`<option value="${esc(o.id)}" ${current===o.id?'selected':''}>${esc(o.title)}</option>`).join('')}${current&&!def.options.some(o=>o.id===current)?`<option value="${esc(current)}" selected>Выбранный вариант недоступен</option>`:''}</select></label>`;}
 function filterForm(params=new URLSearchParams()){
 const p=asParams(params),extra=partitionFacetDefs.slice(3),activeExtra=extra.some(f=>p.get(f.id))||p.get('thickness');
 return `<form id="partitions-filter-form" class="partition-filter-form" action="/catalog/partitions" method="get"><input type="hidden" name="pick" value="1"><div class="partition-filter-primary">${partitionFacetDefs.slice(0,3).map(f=>select(f,p)).join('')}<label for="partition-filter-q">Поиск<input id="partition-filter-q" name="q" type="search" value="${esc(p.get('q')||'')}" placeholder="Например, переговорная или бронза"></label></div><details class="partition-extra-filters" ${activeExtra?'open':''}><summary>Стекло, цвет, декор и оснащение <span>+</span></summary><div>${extra.map(f=>select(f,p)).join('')}<label for="partition-filter-thickness">Толщина листа, мм<input id="partition-filter-thickness" name="thickness" type="number" min="0.1" step="any" value="${esc(p.get('thickness')||'')}" placeholder="Любая"></label></div></details><div class="partition-filter-actions"><button type="submit" class="btn primary">Показать варианты <span>→</span></button><a href="/catalog/partitions?pick=1" class="filter-clear">Сбросить фильтры</a><p>Совместимость стекла, профиля и механизмов уточняем по проекту.</p></div></form>`;
 }
 function rootPage(){return `${crumb([['Каталог','/catalog'],['Перегородки']])}<section class="selection-page partition-hub"><nav class="selection-toolbar" aria-label="Вернуться к выбору"><a class="selection-back" href="/catalog">← Все направления</a><a class="selection-map" href="/structure">Карта каталога ↗</a></nav><header class="selection-heading"><div class="eyebrow">VIP GLASS / КАТАЛОГ</div><h1>Стеклянные перегородки</h1><p>Выберите конструкцию или стекло с управляемой видимостью. Дальше — назначение, открывание и материалы.</p></header><nav class="partition-entry-grid" aria-label="Выберите направление перегородок">${root().children.map(systemCard).join('')}</nav>${directory()}<section class="partition-find"><div class="section-top"><div><span class="eyebrow">УЖЕ ЗНАЕТЕ, ЧТО ИЩЕТЕ?</span><h2>Подбор по параметрам</h2></div><p>Фильтры находят готовые страницы каталога. Можно сочетать систему, место, открывание и свойства стекла.</p></div>${filterForm()}</section><div class="partition-links"><a href="/materials"><span>Стекло и зеркала</span><strong>Каталог материалов ↗</strong></a><a href="/hardware/partitions"><span>Элементы конструкций</span><strong>Фурнитура и отделки ↗</strong></a><a href="/portfolio?product=partitions"><span>Истории проектов</span><strong>Портфолио перегородок ↗</strong></a></div><section class="partition-glazing-note"><h2>Одинарное и двойное остекление</h2><p>В каркасных системах отдельно представлены один ряд стекла и два ряда без герметичной камеры между ними. Для двойного остекления есть варианты с межстекольными жалюзи. Тип и толщину каждого стекла подбирают вместе с профилем и условиями применения.</p></section></section>`;}
 function resultsPage(params=new URLSearchParams()){
 const p=asParams(params),models=filterPartitionModels(p),pageCount=Math.max(1,Math.ceil(models.length/24)),page=Math.max(1,Math.min(pageCount,Number.parseInt(p.get('page')||'1',10)||1));
 const link=n=>{const q=new URLSearchParams(p);q.set('pick','1');q.set('page',String(n));return '/catalog/partitions?'+q;};
 return `${crumb([['Каталог','/catalog'],['Перегородки','/catalog/partitions'],['Подбор по параметрам']])}<section class="selection-page partition-results">${systemNavigation(root())}<header class="selection-heading"><div class="eyebrow">ПЕРЕГОРОДКИ / ПОДБОР</div><h1>Найдите своё<br><em>сочетание.</em></h1><p>Конструкции и варианты комплектации имеют отдельные страницы. Откройте карточку, чтобы уточнить состав выбранного решения.</p></header>${filterForm(p)}<p class="resource-result-count" role="status" data-partitions-result-count="${models.length}">Найдено: ${count(models.length)}${models.length>24?` · страница ${page} из ${pageCount}`:''}</p>${models.length?`<div class="choice-grid partition-results-grid">${models.slice((page-1)*24,page*24).map(finalCard).join('')}</div>`:`<div class="empty"><h2>Такое сочетание пока не представлено.</h2><p>Измените фильтр или опишите индивидуальную задачу.</p><div class="button-row">${btn('Все варианты','/catalog/partitions?pick=1','clear')}${btn('Описать проект','/project','clear')}</div></div>`}${pageCount>1?`<nav class="partition-pagination" aria-label="Страницы результатов">${page>1?btn('Предыдущая',link(page-1),'clear'):''}<span>${page} / ${pageCount}</span>${page<pageCount?btn('Следующая',link(page+1),'clear'):''}</nav>`:''}</section>`;
 }
 function specificationFields(node){if(node?.category!=='partitions')return '';const preset=node.preset||{},specific=Number(preset.thicknessMm)>0,canSet=!['laminated','laminated-tempered','film','smart-laminate','smart-film'].includes(preset.glassTreatmentId)&&node.modelKind!=='privacy-option';return `<fieldset class="partition-spec-fields"><legend>Остекление перегородки</legend>${node.modelKind&&node.modelKind!=='configuration'?'<p>Выбран вариант комплектации. Укажите размеры и задачу перегородки, в которой он будет применяться.</p>':''}${canSet?`<div class="field"><label for="partition-thickness">Толщина одного листа, мм — пожелание</label><input id="partition-thickness" name="partition-thickness" type="number" min="0.1" step="any" value="${specific?Number(preset.thicknessMm):''}" ${specific?'readonly':'placeholder="Подобрать по проекту"'}></div>`:''}<p class="form-note">${preset.glazingId==='double'?'Двойное остекление — два отдельных ряда стёкол. ':''}Толщина и состав утверждаются после проверки размеров, профиля и назначения. ${preset.glassTreatmentId==='annealed'?'Незакалённое стекло рассматривается только для допустимой по проекту области применения.':''}</p></fieldset>`;}
 return {rootPage,systemNavigation,filterForm,resultsPage,specificationFields};
}
